  const transferRe = new RegExp(`([\\d.]+)\\s*(?:pot)?\\s+to\\s+(${TARGET})`, "gi");
  const transfers = [];
  let tm;
  while ((tm = transferRe.exec(text)) !== null) transfers.push({ to: resolveName(tm[2]), amountPot: tm[1] });
